CREATE OR REPLACE PROCEDURE public.sp_update_journey_entry(IN p_id uuid, IN p_tenant_id uuid, IN p_journey_type character varying, IN p_title character varying, IN p_observation text, IN p_child_voice text, IN p_teacher_reflection text, IN p_observation_date timestamp with time zone, IN p_participation_type character varying, IN p_is_milestone boolean, IN p_is_parent_visible boolean, IN p_parent_visibility_status character varying, IN p_updated_at timestamp with time zone, IN p_updated_by uuid)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE child_journey_entries SET         journey_type = p_journey_type,         title = p_title,         observation = p_observation,         child_voice = p_child_voice,         teacher_reflection = p_teacher_reflection,         observation_date = p_observation_date,         participation_type = p_participation_type,         is_milestone = p_is_milestone,         is_parent_visible = p_is_parent_visible,         parent_visibility_status = p_parent_visibility_status,         updated_at = p_updated_at,         updated_by = p_updated_by,         version = version + 1     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
